INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(12201, 'Job 14:8', 'Job', 14, 8, '&nbsp;اګر چې د دې جرړې په زمکه کښې زړيږى، او د دې مونډ په زمکه کښې ورَستيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12202, 'Job 14:9', 'Job', 14, 9, '&nbsp;خو يو څاڅکى اوبو سره به دا بيا را شنه شى، او د يوې نوې ونې په شان به دا بيا څانګې ونيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12203, 'Job 14:10', 'Job', 14, 10, '&nbsp;خو چې انسان مړ شى نو طاقت يې ختم شى، چې انسان ساه ورکړى نو بيا چرته وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12204, 'Job 14:11', 'Job', 14, 11, '&nbsp;لکه څنګه چې د يو ډنډ اوبۀ کميږى، او په سيند کښې اوبۀ اوچيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12205, 'Job 14:12', 'Job', 14, 12, '&nbsp;نو انسان په قبر کښې څملى او بيا نۀ راپاڅى، چې ترڅو پورې آسمانونه ختم شوى نۀ وى، نو هغوئ به د خپل خوب نه نۀ راپاڅى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12206, 'Job 14:13', 'Job', 14, 13, '&nbsp;کاش، چې تا زۀ په قبر کښې پټ کړے وے، او چې تر هغې پورې دې زۀ فنا کړے وے چې ستا غصه تېره شوے وے، او يا دې يو وخت مقرر کړے وے چې زۀ دې راپه ياد شوے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12207, 'Job 14:14', 'Job', 14, 14, '&nbsp;چې انسان ختم شى، نو هغه بيا ژوندے کېدے شى څۀ؟ زۀ به زما د سخت محنت په دې ټولو ورځو کښې اِنتظار کوم تر هغې پورې چې زما تکليف ختم شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12208, 'Job 14:15', 'Job', 14, 15, '&nbsp;تۀ به ما ته آواز وکړې او زۀ به جواب درکړم، تۀ به د هغه مخلوق ارمان وکړې چې تا پېدا کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12209, 'Job 14:16', 'Job', 14, 16, '&nbsp;بيا به تۀ زما په هر قدم باندې نظر ساتې، خو زما د ګناهونو حساب به نۀ کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12210, 'Job 14:17', 'Job', 14, 17, '&nbsp;زما ګناهونه به په يوه بوجۍ کښې بند شوې وى، او تۀ به زما ټولې غلطيانې پټې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12211, 'Job 14:18', 'Job', 14, 18, '&nbsp;خو غر راوغورزيږى او ټوټې ټوټې شى، او غټ غټ کاڼى د خپل ځائ نه وخوځيږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12212, 'Job 14:19', 'Job', 14, 19, '&nbsp;اوبۀ کاڼى مږى، او سېلاب د زمکې خاوره اوړى، نو داسې تۀ د انسان اُميد تباه کوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12213, 'Job 14:20', 'Job', 14, 20, '&nbsp;تۀ په هغوئ باندې تل غالب يې او هغوئ ختميږى، تۀ د هغوئ شکلونه بدلوې او د مرګ په طرف يې بوځې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12214, 'Job 14:21', 'Job', 14, 21, '&nbsp;کۀ د هغۀ بچو ته عزت مِلاو شى، نو هغۀ ته پته نۀ لګى، او کۀ د هغۀ د بچو سپکاوے وشى نو هم هغۀ ته پته نۀ لګى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12215, 'Job 14:22', 'Job', 14, 22, '&nbsp;هغۀ ته صِرف د خپل بدن درد محسوسيږى، او هغه صرف په خپل غم کښې آخته وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12216, 'Job 15:1', 'Job', 15, 1, '&nbsp;نو تيمانى اليفز جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12217, 'Job 15:2', 'Job', 15, 2, '&nbsp;”يو هوښيار کس دې تشې خبرې وکړى څۀ، او هغه دې هسې بې‌مطلبه خبرې وکړى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12218, 'Job 15:3', 'Job', 15, 3, '&nbsp;هغوئ دې په بې‌فائدې خبرو باندې بحث کوى څۀ، يا په داسې خبرو باندې چې د هغې هيڅ مقصد نۀ وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12219, 'Job 15:4', 'Job', 15, 4, '&nbsp;خو تۀ د خُدائ پاک نه هيڅ يره نۀ لرې، او د خُدائ پاک د عبادت لاره نيسې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12220, 'Job 15:5', 'Job', 15, 5, '&nbsp;ځکه چې ستا ګناه ستا ژبې ته ښودنه کوى، او تا د دوکه باز ژبه خوښه کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12221, 'Job 15:6', 'Job', 15, 6, '&nbsp;دا زۀ نۀ يم، خپله ژبه تا ته بد وائى، ستا خپله خولۀ ستا خِلاف ګواهى ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12222, 'Job 15:7', 'Job', 15, 7, '&nbsp;تۀ د بنى آدم د نسل وړومبے پېدا شوے کس يې څۀ؟ تۀ د غرونو نه مخکښې پېدا شوے يې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12223, 'Job 15:8', 'Job', 15, 8, '&nbsp;تا د خُدائ پاک د راز منصوبې واورېدې څۀ؟ او ستا څۀ خيال دے ولې تۀ يواځې هوښيار يې څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12224, 'Job 15:9', 'Job', 15, 9, '&nbsp;تا سره داسې څۀ عِلم دے چې مونږ سره نشته؟ تۀ داسې په څۀ پوهېږې چې مونږ پرې نۀ پوهيږو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12225, 'Job 15:10', 'Job', 15, 10, '&nbsp;سپين‌ږيرى او بوډاګان زمونږ په طرف باندې دى، کوم چې ستا د پلار نه ډېر مشران دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12226, 'Job 15:11', 'Job', 15, 11, '&nbsp;د خُدائ پاک تسلى ستا دپاره کمه ده څۀ؟ د هغۀ نرمې خبرې ستا دپاره کافى نۀ دى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12227, 'Job 15:12', 'Job', 15, 12, '&nbsp;تۀ د خپلو جذباتو نه کار ولې اخلې؟ او ستا رنګ ولې دومره سور دے', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12228, 'Job 15:13', 'Job', 15, 13, '&nbsp;چې خُدائ پاک ته غصه يې؟ او ستا د خولې نه داسې ګډې وډې خبرې وځى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12229, 'Job 15:14', 'Job', 15, 14, '&nbsp;بنى آدم څۀ وى، چې هغه صفا شى؟ او چې د ښځې نه پېدا شى، نو هغه صادق کېدے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12230, 'Job 15:15', 'Job', 15, 15, '&nbsp;ګوره، خُدائ پاک په خپلو فرښتو باندې هم اعتبار نۀ کوى، او د هغۀ په نظر کښې آسمانونه هم صفا نۀ دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12231, 'Job 15:16', 'Job', 15, 16, '&nbsp;نو بيا به بنى آدم نور هم ګنده او ګناه ګار وى، څوک چې هر وخت په ګناه کښې آخته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12232, 'Job 15:17', 'Job', 15, 17, '&nbsp;کۀ تۀ زما خبرې ته غوږ کېږدې، نو زۀ به تا ته وښايم، او چې ما څۀ ليدلى وى نو زۀ به درته د هغې بيان وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12233, 'Job 15:18', 'Job', 15, 18, '&nbsp;څۀ چې هوښيارانو وئيلى دى، نو د هغوئ پلار نيکۀ دا خبرې د هغوئ نه پټى نۀ دې ساتلې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12234, 'Job 15:19', 'Job', 15, 19, '&nbsp;کومو مشرانو له چې ډېره موده مخکښې دا مُلک ورکړے شو او چې په هغه وخت کښې لا غېر قومونه نۀ وو راغلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12235, 'Job 15:20', 'Job', 15, 20, '&nbsp;بدعمله خلق ټول عمر په خپل درد کړيږى، د تکليف کالونه په ظالمانو باندې راجمع شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12236, 'Job 15:21', 'Job', 15, 21, '&nbsp;د هغوئ په غوږُونو کښې يروونکى آوازونه دى، د امن په وخت کښې به په هغوئ باندې تباهى راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12237, 'Job 15:22', 'Job', 15, 22, '&nbsp;هغوئ تيارۀ ته د تلو همت نۀ شى کولے، د هغوئ ژوند هر وخت په خطره کښې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12238, 'Job 15:23', 'Job', 15, 23, '&nbsp;ټپوسان انتظار کوى چې د هغوئ غوښې وخورى، او تباهى د هغوئ سر له راغلې ده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12239, 'Job 15:24', 'Job', 15, 24, '&nbsp;پرېشانى او تکليف هغوئ ويروى، او دا څيزونه په هغوئ باندې غالِب شى، داسې لکه چې يو بادشاه د جنګ دپاره تيار شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12240, 'Job 15:25', 'Job', 15, 25, '&nbsp;ځکه چې هغوئ خپل لاسونه د خُدائ پاک خِلاف اوچت کړل، او هغوئ د قادر خُدائ نه بغاوت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12241, 'Job 15:26', 'Job', 15, 26, '&nbsp;هغوئ د هغۀ خِلاف د سرکشۍ سره حمله کوى، او يو غټ ډال ورسره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12242, 'Job 15:27', 'Job', 15, 27, '&nbsp;دا بدعمله خلق درانۀ او مالدار دى، د هغوئ څټونه په وازګه باندې غټ شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12243, 'Job 15:28', 'Job', 15, 28, '&nbsp;هغوئ به په تباه شوى ښارونو کښې ژوند تېروى، او په داسې کورَنو کښې چې په هغې کښې هيڅ څوک هم نۀ اوسيږى، داسې کورونه چې په راغورزېدو بدل وى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12244, 'Job 15:29', 'Job', 15, 29, '&nbsp;هغوئ به نۀ مالداره کيږى او د هغوئ مال دولت به نۀ پاتې کيږى، او هغوئ به د زمکې د مخ نه ورک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12245, 'Job 15:30', 'Job', 15, 30, '&nbsp;هغوئ به د تيارې نه ونۀ تښتى، لمبې به د هغوئ څانګې وسوزوى، او د هغوئ ژوند به داسې ختم شى لکه چې هوا د ګلونو غوټۍ ختموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12246, 'Job 15:31', 'Job', 15, 31, '&nbsp;هغوئ دې نور خپل ځان په فانى مالدارۍ باندې نۀ دوکه کوى، ځکه چې هغوئ به تش لاس پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12247, 'Job 15:32', 'Job', 15, 32, '&nbsp;د ونو په شان، چې کله دا ښې شنې وى نو ووهلے شى، او د دې څانګې بيا هيڅکله شنې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12248, 'Job 15:33', 'Job', 15, 33, '&nbsp;او د هغوئ انګور چې لا کچه وى نو وبه غورزيږى، او د زيتُونو د ونو په شان به خپلې د ګلونو غوټۍ ضائع کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12249, 'Job 15:34', 'Job', 15, 34, '&nbsp;ځکه چې د خُدائ پاک نه د منکرو خلقو اولاد به نۀ وى، او څوک چې د رشوت سره مينه کوى نو اور به د هغوئ کورونه سوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12250, 'Job 15:35', 'Job', 15, 35, '&nbsp;داسې خلق نورو ته د نقصان رسولو په سوچ کښې وى، هغوئ شېطانى کوى او د هغوئ زړونه د دوکې نه ډک وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12251, 'Job 16:1', 'Job', 16, 1, '&nbsp;بيا ايُوب جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12252, 'Job 16:2', 'Job', 16, 2, '&nbsp;”زۀ د دې څيزونو نه پخوا خبر يم، او ستاسو خبرې ما له تسلى نۀ راکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12253, 'Job 16:3', 'Job', 16, 3, '&nbsp;ستاسو د هوائى خبرو څۀ حد نشته څۀ؟ يا په څۀ وجه باندې تاسو خبرې نۀ بندوئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12254, 'Job 16:4', 'Job', 16, 4, '&nbsp;کۀ تاسو زما په ځائ وئ نو هم ما ستاسو خِلاف لوئې لوئې خبرې جوړولے شوې، او ستاسو سپکاوے به مې کړے وے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12255, 'Job 16:5', 'Job', 16, 5, '&nbsp;خو کۀ دا زۀ وے، نو ما به ستاسو حوصله افزائى کړے وے. او ما به دا کوشش کړے وے چې ستاسو غم لرې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12256, 'Job 16:6', 'Job', 16, 6, '&nbsp;خو کۀ زۀ د خپل ځان صفائى پېش کوم نو زۀ به په تکليف کښې کېږم، خو کۀ زۀ خبرې نۀ کوم نو ما ته بيا هم ډېر تکليف رارسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12257, 'Job 16:7', 'Job', 16, 7, '&nbsp;اے خُدايه پاکه، زۀ اوس تا ډېر ستومانه کړے يم، تا زما مکمل خاندان تباه کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12258, 'Job 16:8', 'Job', 16, 8, '&nbsp;تا زۀ ګېر کړے يم، او دا زما خِلاف يو ثبوت دے، چې زۀ اوچ کلک او کمزورے شوے يم، او دا زما خِلاف ګواهى ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12259, 'Job 16:9', 'Job', 16, 9, '&nbsp;هغۀ د خپلې غصې په وجه زۀ خراب کړے يم او زما نه نفرت کوى، هغۀ ما ته خپل غاښونه چيچلى دى، زما دشمن د هغۀ سترګې زما خِلاف برندوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12260, 'Job 16:10', 'Job', 16, 10, '&nbsp;خلق ما پورې خندا کوى، هغوئ په مسخرو کښې ما په مخ باندې وهى او زما خِلاف يې اتفاق کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12261, 'Job 16:11', 'Job', 16, 11, '&nbsp;خُدائ پاک ما د خُدائ نه منکرو خلقو له ورکوى، او د بدعمله خلقو لاسونو ته مې حواله کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12262, 'Job 16:12', 'Job', 16, 12, '&nbsp;زۀ صحيح سلامت وم او هغۀ زۀ دوه ټوټې کړم، هغۀ زۀ د څټ نه ونيولم او ټوټې ټوټې يې کړم، هغۀ زۀ د خپلې نښې په توګه ودرولم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12263, 'Job 16:13', 'Job', 16, 13, '&nbsp;د هغۀ غشى ويشتونکى زما نه تاو شول. هغۀ زما ګردې راوويستلې او په ما يې هيڅ رحم ونۀ کړو، هغۀ زما تريخے په زمکه بهر وغورزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12264, 'Job 16:14', 'Job', 16, 14, '&nbsp;هغۀ زۀ بيا مات رامات کړم، هغۀ د يو جنګيالى په شان په ما باندې رامنډه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12265, 'Job 16:15', 'Job', 16, 15, '&nbsp;ما د ځان دپاره د ټاټ جامې ګنډلې دى، او هغۀ زۀ د خاورې په شان مېده کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12266, 'Job 16:16', 'Job', 16, 16, '&nbsp;زما سترګې د ژړا نه سرې دى، او زما د سترګو ليمۀ تور شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12267, 'Job 16:17', 'Job', 16, 17, '&nbsp;اګر چې ما هيڅ ظلم زياتے نۀ دے کړے، او زما په دُعا کښې خلوص دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12268, 'Job 16:18', 'Job', 16, 18, '&nbsp;اے زمکې، زما وينه مۀ پټوه، او زما د اِنصاف فرياد دې څوک نۀ ختموى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12269, 'Job 16:19', 'Job', 16, 19, '&nbsp;خو بيا هم په آسمان کښې داسې ذات شته چې هغه زما مل دے او هغه به بې‌شکه ووائى چې زۀ په حقه يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12270, 'Job 16:20', 'Job', 16, 20, '&nbsp;زما مينځګړے زما دوست دے او زما سترګې خُدائ پاک ته اوښکې تويوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12271, 'Job 16:21', 'Job', 16, 21, '&nbsp;او زما دوست زما دپاره خُدائ پاک سره بحث کوى لکه څنګه چې يو سړے د خپل دوست دپاره مِنت زارى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12272, 'Job 16:22', 'Job', 16, 22, '&nbsp;صِرف يو څو کاله به پاتې وى چې زۀ به په هغه سفر باندې روان شم چې د هغې نه واپس کېدل نشته.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12273, 'Job 17:1', 'Job', 17, 1, '&nbsp;زما زور ختم شوے دے او زما ورځې لنډې شوې دى، او قبر زما دپاره تيار دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12274, 'Job 17:2', 'Job', 17, 2, '&nbsp;زما نه ګېرچاپېره مسخرې کوونکى راتاو دى، او زۀ ګورم چې هغوئ ما ته سپکې خبرې کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12275, 'Job 17:3', 'Job', 17, 3, '&nbsp;اے خُدايه پاکه، تۀ زما ضمانت وکړه، ځکه چې بل هيڅ څوک به زما ذمه وارى وانۀ خلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12276, 'Job 17:4', 'Job', 17, 4, '&nbsp;ځکه چې تا د هغوئ په ذهنونو باندې پړدې لګولې دى، هغوئ مۀ پرېږده چې په ما غالب شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12277, 'Job 17:5', 'Job', 17, 5, '&nbsp;څوک چې د خپلې فائدې دپاره دوستان دوکه کوى، نو د هغوئ د اولاد سترګې به ړندې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12278, 'Job 17:6', 'Job', 17, 6, '&nbsp;خُدائ پاک زۀ د خلقو دپاره د خندا کړے يم، هغوئ زما په مخ باندې توکاڼى توکى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12279, 'Job 17:7', 'Job', 17, 7, '&nbsp;د غم په وجه زما سترګې سرې شوې دى، او زما بدن اوچ کلک شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12280, 'Job 17:8', 'Job', 17, 8, '&nbsp;کله چې نېکان خلق ما وګورى نو په لړزان شى، او بې‌ګناه خلق د خُدائ پاک نه د منکرو خلقو مخالفت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12281, 'Job 17:9', 'Job', 17, 9, '&nbsp;خو صادقان د خپلې لارې نه نۀ اوړى، چې صادقان ورځ په ورځ نور هم تکړه کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12282, 'Job 17:10', 'Job', 17, 10, '&nbsp;اوس تاسو ټول چرته ما ته څۀ سمه خبره وکړئ، خو بيا به هم په تاسو کښې يو هوښيار کس پېدا نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12283, 'Job 17:11', 'Job', 17, 11, '&nbsp;زما دوران تېر شو او زما منصوبې ناکامه شوې، زما نه زما اُميدونه ختم شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12284, 'Job 17:12', 'Job', 17, 12, '&nbsp;هغوئ د شپې نه ورځ جوړوى، او رڼا ته تيارۀ وائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12285, 'Job 17:13', 'Job', 17, 13, '&nbsp;زۀ د مرګ په طمع يم، او زۀ به تل په تيارۀ کښې پروت يم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12286, 'Job 17:14', 'Job', 17, 14, '&nbsp;کۀ زۀ قبر ته ووايم چې تۀ زما پلار يې، او چينجو ته ووايم چې تاسو زما مور يا خور يئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12287, 'Job 17:15', 'Job', 17, 15, '&nbsp;نو بيا زما اُميد چرته دے؟ او دا چا ته ښکارى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12288, 'Job 17:16', 'Job', 17, 16, '&nbsp;نو زما ټول اُميدونه به په قبر کښې فنا شى؟ او زما ټول ارمانونه به خاورې شى څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12289, 'Job 18:1', 'Job', 18, 1, '&nbsp;بيا شوحى بِلداد جواب ورکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12290, 'Job 18:2', 'Job', 18, 2, '&nbsp;”تر کومې پورې به تۀ خبرې کوې؟ د مطلب خبره کوه، نو بيا به مونږ خبرې وکړُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12291, 'Job 18:3', 'Job', 18, 3, '&nbsp;مونږ په ځناورو کښې ولې شمېرلے شُو؟ مونږ ستاسو په نظر کښې ولې کم عقلان يُو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12292, 'Job 18:4', 'Job', 18, 4, '&nbsp;تۀ په غصه کښې هسې خپل ځان سوزوې، ستا دپاره دې دُنيا پرېښودلے شى څۀ، يا غرونه دې ستا دپاره د خپل ځائ نه لرې کړے شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12293, 'Job 18:5', 'Job', 18, 5, '&nbsp;په حقيقت کښې د بدعمله خلقو ډيوه ختمه کړے شوې ده، او بيا به د هغې شُغلې بلې نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12294, 'Job 18:6', 'Job', 18, 6, '&nbsp;د هغوئ په خېمه کښې رڼا په تيارۀ بدله شوې ده، او د هغوئ دپاسه ډيوه مړه کړے شوې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12295, 'Job 18:7', 'Job', 18, 7, '&nbsp;د هغوئ مضبوط قدمونه خطا شوى دى، او د هغوئ خپلو منصوبو هغوئ ناکامه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12296, 'Job 18:8', 'Job', 18, 8, '&nbsp;ځکه چې هغوئ په يو جال کښې انښتى دى، او هغوئ په يوه کنده کښې پرېوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12297, 'Job 18:9', 'Job', 18, 9, '&nbsp;د هغوئ پونده په دام کښې ګېريږى، او هغه يې کلک ونيسى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12298, 'Job 18:10', 'Job', 18, 10, '&nbsp;يو جال په زمکه کښې پټ دے، او د هغوئ په لاره کښې يو دام پټ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12299, 'Job 18:11', 'Job', 18, 11, '&nbsp;هغوئ د هر طرف نه يريږى، او چې چرته هم ځى نو يره ورپسې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(12300, 'Job 18:12', 'Job', 18, 12, '&nbsp;د هغوئ طاقت د لوږې په وجه ختم شوے دے، او تباهى د هغوئ د غلطۍ په انتظار کښې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');